(function() {
    // 🎯 Just enter the code for your preferred language here!😎 (e.g.: "tr", "en", "bn", "ar")
    const TARGET_LANG = "en"; 

    console.log(`🚀 Nova AI Auto-Translator Active! Target Language: ${TARGET_LANG}`);

    const translatedCache = new Set();

    async function translateNode(node) {

        if (node.nodeType === 3 && node.nodeValue.trim().length > 1) {
            let text = node.nodeValue.trim();

            if (!translatedCache.has(text)) {

                translatedCache.add(text);

                try {
                    let res = await fetch(`https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=${TARGET_LANG}&dt=t&q=${encodeURIComponent(text)}`);
                    let data = await res.json();

                    if (data && data[0]) {
                        let translatedText = data[0].map(p => p[0]).join('');
                        node.nodeValue = translatedText;


                        translatedCache.add(translatedText.trim());
                    }
                } catch (e) {
                    console.error("Translation Error:", e);
                }
            }
        } 

        else if (node.nodeType === 1 && !['SCRIPT', 'STYLE', 'CODE', 'NOSCRIPT'].includes(node.tagName)) {
            for (let child of node.childNodes) {
                await translateNode(child);
            }
        }
    }


    translateNode(document.body);

MutationObserver
    const observer = new MutationObserver((mutations) => {
        mutations.forEach((mutation) => {
            mutation.addedNodes.forEach((node) => {

                setTimeout(() => translateNode(node), 100);
            });
        });
    });
    observer.observe(document.body, { childList: true, subtree: true });

    console.log("👻 Stealth Mode On: All current and future texts will be translated automatically! 😏");
})();
